  2xy + x + y = z                                 
  (2x + 1) (2y + 1) = 2z + 1                      
  x' * y' = z'                                    
  check z' for prime number.                      
"""
prime = dict()
prime_nums = list()
MAXIMUM = 2 ** 16

def get_prime():
    for i in range(2, MAXIMUM):
        if prime.get(i, True):
            prime_nums.append(i)
            for j in range(i * 2, MAXIMUM, i):
                prime[j] = False

def check(x):
    x = 2 * x + 1
    for prime in prime_nums:
        if prime ** 2 > x:
            break
        if x % prime == 0:
            return False
    return True
