def dfs(v, p):
    dpB = {}
    dpW = {}
    dpB[0] = 0
    dpW[0] = 0
    for nex in lis[v]:
        if nex != p:
            ndpB = {}
            ndpW = {}
            b1, w1, b2, w2 = dfs(nex, v)
            for b in dpB:
                if b + b1 > X[v]:
                    continue
                if b + b1 not in ndpB:
                    ndpB[b + b1] = float('inf')
                ndpB[b + b1] = min(ndpB[b + b1], dpB[b] + w1)
            for b in dpB:
                if b + b2 > X[v]:
                    continue
                if b + b2 not in ndpB:
                    ndpB[b + b2] = float('inf')
                ndpB[b + b2] = min(ndpB[b + b2], dpB[b] + w2)
            for w in dpW:
                if w + w1 > X[v]:
                    continue
                if w + w1 not in ndpW:
                    ndpW[w + w1] = float('inf')
                ndpW[w + w1] = min(ndpW[w + w1], dpW[w] + b1)
            for w in dpW:
                if w + w2 > X[v]:
                    continue
                if w + w2 not in ndpW:
                    ndpW[w + w2] = float('inf')
                ndpW[w + w2] = min(ndpW[w + w2], dpW[w] + b2)
            dpB = ndpB
            dpW = ndpW
    b1 = X[v]
    w1 = float('inf')
    for i in dpB:
        w1 = min(w1, dpB[i])
    w2 = X[v]
    b2 = float('inf')
    for i in dpW:
        b2 = min(b2, dpW[i])
    if w1 == float('inf') and b2 == float('inf'):
        print('IMPOSSIBLE')
        sys.exit()
    print(dpB, dpW, file=sys.stderr)
    return (b1, w1, b2, w2)
