import math

class seg_tree:

    def __init__(self, n):
        self.depth = math.ceil(math.log(n, 2))
        self.size = 1 << self.depth
        self.bit = [0] * 2 * self.size
        self.renew = [0] * 2 * self.size

    def add(self, p, v):
        p += self.size
        while p:
            self.bit[p] += v
            p >>= 1

    def query(self, l, r):
        l += self.size
        r += self.size
        ret = 0
        while l < r:
            if l & 1:
                ret += self.bit[l]
                l += 1
            if r & 1:
                r -= 1
                ret += self.bit[r]
            l >>= 1
            r >>= 1
        return ret

    def set_renew(self, l, r):
        l += self.size
        r += self.size
        while l < r:
            if l & 1:
                self.renew[l] = 1
                l += 1
            if r & 1:
                r -= 1
                self.renew[r] = 1
            l >>= 1
            r >>= 1

    def is_renew(self, p):
        p += self.size
        while p:
            if self.renew[p]:
                return True
            p >>= 1
        return False

    def unset_renew(self, p):
        p += self.size
        for i in range(self.depth - 1, 0, -1):
            if self.renew[p >> i]:
                self.renew[p >> i] = 0
                self.renew[(p >> i) * 2] = self.renew[(p >> i) * 2 + 1] = 1
        self.renew[p] = 0

    def get_lf(self, r):
        l = self.size
        r += self.size
        while l < r:
            if r & 1:
                r -= 1
                if self.bit[r]:
                    while r < self.size:
                        r <<= 1
                        if self.bit[r + 1]:
                            r += 1
                    return r - self.size
            if l & 1:
                l += 1
            l >>= 1
            r >>= 1
        return -1
from collections import UserList

class union_find(UserList):

    def __init__(self):
        UserList.__init__(self)

    def root(self, p):
        if self.data[p] < 0:
            return p
        self.data[p] = self.root(self.data[p])
        return self.data[p]

    def join(self, p, q):
        p, q = (self.root(p), self.root(q))
        if p == q:
            return False
        if self.data[p] < self.data[q]:
            p, q = (q, p)
        self.data[p], self.data[q] = (self.data[q], p)
        return True

def bisect(a, v):
    l, r = (0, len(a))
    while l < r:
        m = (l + r) // 2
        if a[m] < v:
            l = m + 1
        else:
            r = m
    return l

