    if z.left == None or z.right == None:
        y = z
    else:
        y = get_successor(z)
    if y.left != None:
        x = y.left
    else:
        x = y.right
    if x != None:
        x.parent = y.parent
    if y.parent == None:
        root = x
    elif y == y.parent.left:
        y.parent.left = x
    else:
        y.parent.right = x
    if y != z:
        z.key = y.key

def get_successor(x):
    if x.right != None:
        return get_min(x.right)
    y = x.parent
    while y != None and x == y.right:
        x = y
        y = y.parent
    return y

