def printBoard(x, row):
    for i in range(N):
        for j in range(N):
            if x[i][j]:
                if row[i] != j:
                    return
    for i in range(N):
        line = ''
        for j in range(N):
            if row[i] == j:
                line += 'Q'
            else:
                line += '.'
