def recursive(i, x, row, col, dpos, dneg):
    if i == N:
        printBoard(x, row)
        return
    for j in range(N):
        if NOT_FREE == col[j] or NOT_FREE == dpos[i + j] or NOT_FREE == dneg[i - j + N - 1]:
            continue
        row[i] = j
        col[j] = NOT_FREE
        dpos[i + j] = NOT_FREE
        dneg[i - j + N - 1] = NOT_FREE
        recursive(i + 1, x, row, col, dpos, dneg)
        row[i] = FREE
        col[j] = FREE
        dpos[i + j] = FREE
        dneg[i - j + N - 1] = FREE
