    maxA = max(A)
    segment_tree = SegmentTree([0] * (maxA + 1))
    for a in A:
        count = segment_tree.max(max(0, a - K), min(maxA, a + K) + 1)
        segment_tree.set(a, count + 1)
    return segment_tree.max(0, maxA + 1)
