"""

https://atcoder.jp/contests/caddi2018/tasks/caddi2018_d

インラインdpを習得したから再挑戦
2*2→3*3…と塗っていくと、毎回2個を決めることとなる

新たに塗る2箇所をどう決められるかを考える
→偶奇を反転させる場合、01 or 10で塗り、させない場合は11 or 00で塗る
→1箇所までなら塗られていても自由度が下がるだけ？
→両方塗られていたらまずい場合がある

基本的に4列目以降は00 01の対以外不可能になる
→すでに片側置かれていたら1択、両側でダメだったら0になる
→つまり、考えるべきは3列目までである

3列目までは、片側は問題ないが、両側は制約として作動する
1列目(i=j)は文字を確定させる
2列目(abs(i-j)!=1)は隣り合う文字が同じ or 異なるを確定させる
3列目は、1列目の文字を確定させる

"""
from sys import stdin
import sys
mod = 998244353
N, M = map(int, stdin.readline().split())
neq = {}
eq = [None] * N
lock = [None] * (N - 1)
for loop in range(M):
    a, b, c = map(int, stdin.readline().split())
    a -= 1
    b -= 1
    if a < b:
        a, b = (b, a)
    if a == b:
        if eq[a] == None or eq[a] == c:
            eq[a] = c
        else:
            print(0)
            sys.exit()
    elif a - b == 1:
        if (a, b) in neq:
            lock[b] = neq[a, b] ^ c
        else:
            neq[a, b] = c
    elif a - b == 2:
        if (a, b) in neq:
            if eq[a - 1] == None or eq[a - 1] == neq[a, b] ^ c:
                eq[a - 1] = neq[a, b] ^ c
            else:
                print(0)
                sys.exit()
        else:
            neq[a, b] = c
    elif (a, b) in neq:
        if neq[a, b] ^ c == 1:
            print(0)
            sys.exit()
    else:
        neq[a, b] = c
ableout = (N ** 2 - N) // 2 - len(neq)
outans = pow(2, ableout, mod)
dp = [[0, 0] for i in range(N)]
dp[0] = [1, 1]
for i in range(N):
    if eq[i] == 0:
        dp[i][1] = 0
    if eq[i] == 1:
        dp[i][0] = 0
    if i == N - 1:
        break
    if lock[i] == 0:
        dp[i + 1][0] = dp[i][0]
        dp[i + 1][1] = dp[i][1]
    elif lock[i] == 1:
        dp[i + 1][0] = dp[i][1]
        dp[i + 1][1] = dp[i][0]
    else:
        dp[i + 1][0] = sum(dp[i]) % mod
        dp[i + 1][1] = sum(dp[i]) % mod
print(sum(dp[-1]) * outans % mod)

