def minHeapify(Q, i):
    H = len(Q)
    l = 2 * i
    r = 2 * i + 1
    if l < H and Q[l][1] < Q[i][1]:
        smallest = l
    else:
        smallest = i
    if r < H and Q[r][1] < Q[smallest][1]:
        smallest = r
    if smallest != i:
        Q[i], Q[smallest] = (Q[smallest], Q[i])
        minHeapify(Q, smallest)

