def reverse_polish_notation(exp):
    priority = {'+': 0, '-': 0, '/': 1, '*': 1}
    exp = deque(exp)
    stack = deque()
    buffer = deque()
    while len(exp):
        token = exp.pop()
        if token.isnumeric():
            buffer.append(token)
        elif token == '(':
            while True:
                token = stack.pop()
                if token == ')':
                    break
                buffer.append(token)
        elif token == ')':
            stack.append(token)
        else:
            while len(stack):
                if stack[-1] == ')' or priority[stack[-1]] <= priority[token]:
                    break
                buffer.append(stack.pop())
            stack.append(token)
    while len(stack):
        buffer.append(stack.pop())
    return buffer

