def solve(l, n, jota_weights):
    jota_torque = sum((x * w for x, w in jota_weights))
    if jota_torque == 0:
        return (0, [])
    else:
        max_w = 50000
        sign = -1 if jota_torque > 0 else 1
        ritsuko_weights = []
        ritsuko_counter = 0
        weight = 0
        remainder = abs(jota_torque)
        for x in range(l, 0, -1):
